architecture.h4_f:
msg = CBOR{v:1, teksti, vastaus_osoite, lähetetty_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/huoneet/{id}/viestit {salausteksti: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, mainings?, sent_at}
ct = AES-GCM-256-Salaa(huoneavain, nonce, pt, aad=hex(huoneen_id))
lanka = CBOR{
  v: 1,
  salakirjoitus: hex(ct), // muuttuva pituus
  nonce: hex(12 B),
  lähettäjä_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
ulompi = CBOR{
  lähde_solmu: hex32,
  kohdekäyttäjä: int64,
  inner_ciphertext: tavua,
  inner_nonce: tavua,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, ulompi)
POST /liitto/toimitus { kirjekuori: ulkoinen, sig: hex64}

auth.h1_f:
POST /api/auhentication/register
  { käyttäjänimi, salasana, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Vastaus 201 Luotu:
  { pääsytunnus, päivitystunnus, käyttäjätunnus, käyttäjänimi, ... }

auth.h3_f:
access_token hyötykuorma:
  { sub: user_id, jti: device_id, typ: "access", ex: nyt + 15 min }
refresh_token hyötykuorma:
  { sub: user_id, jti: device_id, typ: "refresh", ex: nyt + 30p }

HS256-allekirjoitettu solmun 64-tavuisella .env-salauksella

auth.h4_f:
register_begin(): haaste = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    palautusvaihtoehdot

register_finish(todistus):
  tarkista todistus TPM / suojatun enklaavin juuri CA
  myymälä { credential_id, public_key, laskuri: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bittinen hex, ttl: 60 }
QR hyötykuorma = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → uusi laite rekisteröity; JWT:t palasivat.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(huoneen_pseudo_suola, lähettäjän_tunnus)[:16] // 32 hex
salateksti = AES-GCM-Salaus(huoneavain, nonce, CBOR_payload, aad=huoneen_id)

Fan-out kehys: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {tiedostonimi, koko, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL keskeneräisellä: 24 h

files.h4_f:
deny_list = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "sovellus/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) in deny_list: return 415

presence.h1_f:
asiakas: ensimmäisellä näppäimen painalluksella → lähetä {type:"t", tila:"start"}
         ei lähetä enää 3 sekuntiin, ellei tila muutu
         10 s viimeisen painalluksen jälkeen → lähetä {type:"t", tila:"stop"}
vastaanotin: automaattinen pysäytys 10 s viimeisen "käynnistyksen" jälkeen, jos "stop" ei saapunut

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS lähetys {type:"c", kind:"invite", call_id}
WS lähetys {type:"c", kind:"offer", sdp}
WS lähetys {type:"c", kind:"answer", sdp}
WS lähetys {tyyppi:"c", laji:"kandidaatti",jää} × N
POST /api/calls/{call_id}/end

federation.h2_f:
kirjekuori = {
  source_node : hex32,
  kohdekäyttäjä: int64,
  inner_ciphertext: tavua,
  inner_nonce: tavua,
  sent_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(kirjekuori))
POST /liitto/toimita { kirjekuori, merkki }

gossip.h3_f:
mainos = {pubkey, endpoint, mainostettu_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(mainos))
juorujen hyötykuorma: [..., {ad, sig}, ...]

vastaanotin: tarkista sig vastaan ad.pubkey → store iff ok
lisäksi: PoW 2^18 etunollasta {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template with {
  satunnainen = meidän satunnainen,
  palvelimen_nimi = isäntänimemme (tai ECH-kääritty),
  session_id = istuntotunnuksemme,
}
JA4 = t13d_xxxx_xxxx_xxxx (vastaa nykyistä Chromen vakaata)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nimi: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(julkinen_avain_HTTPS_tietueesta)
DGA: verkkotunnus(t) = perus32( SHA256(siemen ∥ YYYY-MM-DD) )[:16] + ".esimerkki"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
työkalu = sign_tool
input = lähdepuu, avaimet/julkaisu.avain
manifest = {
  versio: "0.1.0",
  built_at: unix_ms,
  tiedostot: [{polku, sha256, koko}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
lähtö = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
luo: POST /api/bots {käyttäjänimi, näyttönimi, koodi}
          → {bot_id, tunnus, pubkey}
ajo: prosessin aikana (korutiini solmun sisällä)
      OR ulkoinen (pitkä kysely /api/bots/{id}/updates, token-auth'd)
viesti: {teksti, allekirjoitus: Ed25519-Sign(bot_priv, canonical_msg)}

security.h4_f:
canary.txt (päivittäin):
  {date, sig: Ed25519-Sign(release_priv, date)}
asiakas vahvistaa → puuttuu tai virheellinen ⇒ epäilty vaarantuminen

hätä:
  admin POST /api/admin/revoke-all {reason}
  solmulähetykset {tyyppi:"n", tapahtuma:"kompromissi", syy}
  asiakkaat pyyhkivät avaimet, pakottavat käynnistämään uudelleen

debugging.h2_f:
nopeushistogrammit (per reitti + menetelmä):
  vortex_http_requests_total{route,method,status}
  vortex_http_request_duration_seconds_bucket{route,method,le}

verkkopistorasian mittarit:
  vortex_ws_connections{solmu}
  vortex_ws_fanout_queue_depth{huone,käyttäjä}

mukautetut laskurit:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

