fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  sisältö, -- tokenoitu sarake
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
kysely: SELECT rowid FROM messages_fts WHERE sisältö MATCH 'foo'

